# ─── Action registry — built-in task handlers ─────────────────────────────────

@register_action("heartbeat")
def task_heartbeat(**kwargs):
    """Runs every N seconds — a simple heartbeat."""
    log.info("💓 Heartbeat — system alive at %s", datetime.now().isoformat())


@register_action("cleanup")
def task_cleanup(**kwargs):
    """Runs periodically — simulates a cleanup routine."""
    log.info("🧹 Cleanup task running…")


@register_action("report")
def task_report(**kwargs):
    """Runs on a cron schedule — simulates a periodic report."""
    log.info("📊 Report generated at %s", datetime.now().strftime("%H:%M"))


# ─── exec action ──────────────────────────────────────────────────────────────
# Registered so task_loader can look it up by name "exec".
# The manifest "exec" block is forwarded verbatim as kwargs.

@register_action("exec")
def task_exec(**kwargs):
    """
    Execute a shell command defined in the manifest's ``exec`` block.
    kwargs are the fields from the task's ``"exec": { ... }`` dict, plus
    ``task_id`` injected by make_exec_runner().
    """
    result = exec_action(**kwargs)
    if not result.success and not result.blocked:
        log.warning("Exec task '%s' finished with non-zero status.", result.task_id)
    return result


def make_exec_runner(task: dict):
    """
    Return a zero-argument callable that runs the exec task, injecting
    the task id and exec kwargs from the manifest definition.
    """
    exec_cfg = task.get("exec", {})
    tid      = task["id"]

    def _run():
        kw = dict(exec_cfg)          # copy so concurrent runs don't share state
        kw["task_id"] = tid
        return task_exec(**kw)

    _run.__name__ = f"exec_task_{tid}"
    return _run


# ─── Scheduler integration patch: exec tasks bypass the action registry lookup
# because their callable is built per-task (includes task_id + exec kwargs).

def _build_action_callable(task: dict):
    """
    Return the right callable for a task, whether it's a named action or exec.
    """
    if task["action"] == "exec":
        return make_exec_runner(task)
    fn = get_action(task["action"])
    if fn is None:
        return None
    kw = task.get("kwargs", {})
    return lambda fn=fn, kw=kw: fn(**kw)
